-- Hyprland 0.55+ config (Lua). Hyprland 0.57 dropped hyprland.conf; 0.55/0.56 also pick
-- this file over hyprland.conf when both exist.
--   look.lua     liquid-glass look: gaps, borders, blur, animations, opacity rules
--   plugins.lua  hyprbars, hyprfocus, Hyprspace, dynamic-cursors, HyprGlass
--   colors.lua   generated by matugen from the wallpaper (scripts/wallpaper.sh)
--   monitors.lua written by nwg-displays (per device, gitignored)

local HOME = os.getenv("HOME")
local CFG = HOME .. "/.config/hypr"
local RUNTIME = os.getenv("XDG_RUNTIME_DIR") or "/run/user/1000"
local SCRIPTS = CFG .. "/scripts"

local function exists(path)
    local f = io.open(path, "r")
    if f then f:close() end
    return f ~= nil
end

-- require() a module from ~/.config/hypr only when its file is there (generated / per-device files)
local function optional(mod)
    if exists(CFG .. "/" .. mod .. ".lua") then return require(mod) end
end

-- Shared with look.lua / plugins.lua
COLORS = optional("colors") or {
    primary = "rgb(cfbdfe)", tertiary = "rgb(efb8c8)", error = "rgb(ffb4ab)",
    surface = "rgb(141218)", on_surface = "rgb(e6e0e9)", outline = "rgb(948f99)",
    primary_a = "rgba(cfbdfeee)", tertiary_a = "rgba(efb8c8ee)", outline_dim = "rgba(948f9966)",
    shadow_a = "rgba(00000099)", bar_bg = "rgba(14121873)", glass_card = "rgba(1412188c)",
    glass_tint = "0xcfbdfe1a",
}
WINCTL = SCRIPTS .. "/winctl.sh"


------------------
---- MONITORS ----
------------------

-- Fallback for any output; nwg-displays (Super+Alt+P) writes monitors.lua
hl.monitor({ output = "", mode = "preferred", position = "auto", scale = 1 })
optional("monitors")
hl.monitor({ output = "HDMI-A-1", mode = "1920x1080@60", position = "auto-right", scale = 1 })
hl.monitor({ output = "desc:Xiaomi Corporation Mi Monitor", mode = "1920x1080@200", position = "auto", scale = 1 })
-- Runtime mirror/extend from scripts/display-toggle.sh (tmpfs: cleared on logout). Usually absent.
local override = RUNTIME .. "/hypr-display-override.lua"
if exists(override) then dofile(override) end

-- ws 10 is reserved for the external display; eDP-1 gets ws 1 naturally.
hl.workspace_rule({ workspace = "10", monitor = "HDMI-A-1", default = true })
optional("workspaces")


---------------------
---- ENVIRONMENT ----
---------------------

hl.env("WLR_DRM_NO_ATOMIC", "0")
hl.env("XCURSOR_THEME", "Bibata-Modern-Classic")
hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_THEME", "Bibata-Modern-Classic-Hypr")
hl.env("HYPRCURSOR_SIZE", "24")
hl.env("SSH_AUTH_SOCK", RUNTIME .. "/keyring/ssh")
-- LIBVA_DRIVER_NAME unset: libva picks iHD (Intel) or nvidia from the kernel driver.
-- Intel laptop: GBM_BACKEND=nvidia-drm / __GLX_VENDOR_LIBRARY_NAME=nvidia made
-- apps load NVIDIA's EGL instead of Mesa's iris driver, which made workspace switches drop to ~30 fps.
hl.env("CHROME_EXTRA_FLAGS", "--force-device-scale-factor=1")
hl.env("GDK_SCALE", "1")
hl.env("GDK_DPI_SCALE", "1")
hl.env("XDG_DATA_DIRS", HOME .. "/.local/share/flatpak/exports/share:/var/lib/flatpak/exports/share:/usr/local/share:/usr/share")
hl.env("GTK_THEME", "catppuccin-mocha")
hl.env("QT_QPA_PLATFORMTHEME", "qt6ct")
-- macOS app icons for MacShell only (Dock, Spotlight); GTK/Qt apps keep their theme
hl.env("QS_ICON_THEME", "MacOS-Like-Dark")


-------------------
---- AUTOSTART ----
-------------------

hl.on("hyprland.start", function()
    hl.exec_cmd("dbus-update-activation-environment --systemd DISPLAY WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
    hl.exec_cmd("gnome-keyring-daemon --start --components=secrets")
    hl.exec_cmd("/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1")
    hl.exec_cmd("thunar --daemon")
    -- MacShell: menu bar, Dock, Spotlight, notifications (replaces waybar + dunst). Loop restarts it if it crashes.
    hl.exec_cmd("sh -c 'while :; do qs -c MacShell; sleep 1; done'")
    hl.exec_cmd("blueman-applet")
    hl.exec_cmd("udiskie --automount --notify --no-tray")
    hl.exec_cmd("bluetoothctl power off")
    hl.exec_cmd("wl-paste --type text --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
    hl.exec_cmd("awww-daemon")
    hl.exec_cmd(SCRIPTS .. "/wallpaper.sh --restore")
    hl.exec_cmd(SCRIPTS .. "/livewall.sh --restore")
    hl.exec_cmd(SCRIPTS .. "/wallpaper-hotplug.sh")
    hl.exec_cmd(WINCTL .. " daemon")
end)


---------------
---- INPUT ----
---------------

hl.config({
    misc = {
        disable_hyprland_logo    = true,
        disable_splash_rendering = true,
        force_default_wallpaper  = 0,
    },
    cursor = {
        no_hardware_cursors = true,
        no_warps            = true,
    },
    input = {
        kb_layout    = "us",
        follow_mouse = 1,
        -- keyboard focus changes (Alt+Tab) stick until the cursor crosses into another window
        mouse_refocus = false,
        touchpad = {
            natural_scroll = true,
            scroll_factor  = 0.3,
        },
    },
    general = {
        -- Resize: drag borders/gaps directly, or SUPER+CTRL+arrows (hold to repeat)
        resize_on_border = true,
    },
})

-- 3-finger swipe left/right switches workspace
hl.gesture({ fingers = 3, direction = "horizontal", action = "workspace" })
-- winctl tracks whether the overview is open: 4-finger down closes it, or shows the desktop when it's closed
hl.gesture({ fingers = 3, direction = "up",   action = function() hl.exec_cmd(WINCTL .. " desk up") end })
hl.gesture({ fingers = 3, direction = "down", action = function() hl.exec_cmd(WINCTL .. " desk down") end })


------------------
---- KEYBINDS ----
------------------

local mod = "SUPER"
local function exec(cmd) return hl.dsp.exec_cmd(cmd) end
local function qs(call) return exec("qs -c MacShell ipc call " .. call) end

hl.bind(mod .. " + Return", exec("kitty"))
hl.bind(mod .. " + grave",  exec("kitten quick-access-terminal"))
hl.bind(mod .. " + Escape", hl.dsp.window.close())
hl.bind(mod .. " + M",      hl.dsp.exit())
hl.bind(mod .. " + E",      exec("thunar"))
hl.bind(mod .. " + T",      exec(WINCTL .. " max"))
hl.bind(mod .. " + F",      hl.dsp.window.fullscreen())
hl.bind(mod .. " + D",      hl.dsp.focus({ workspace = "empty" }))
hl.bind(mod .. " + L",      exec("hyprlock"))
hl.bind(mod .. " + Tab",    exec(WINCTL .. " desk toggle"))

-- MacShell: Spotlight on a lone Super tap, emoji, Alt+Tab switcher, wallpapers, clipboard
hl.bind(mod .. " + SUPER_L",    qs("spotlight toggle"), { release = true })
hl.bind(mod .. " + period",     qs("spotlight emoji"))
hl.bind("ALT + Tab",            qs("switcher next $(date +%s%3N)"))
hl.bind("ALT + SHIFT + Tab",    qs("switcher prev $(date +%s%3N)"))
-- Alt release -> commit. A release bind never fires once Alt was used in the Alt+Tab combo, so watch raw key
-- events instead: Tab while Alt is held arms it, the next Alt release (left or right) sends `switcher commit`.
-- Hyprland sends it itself because a fast Alt+Tab releases Alt before the switcher layer has keyboard focus.
local altHeld, switcherArmed = 0, false
hl.on("input.keyboard.key", function(code, _, state)
    if code == 64 or code == 108 then                      -- Alt_L / Alt_R (xkb keycodes)
        altHeld = altHeld + (state == 1 and 1 or -1)
        if altHeld < 0 then altHeld = 0 end
        if state == 0 and switcherArmed then
            switcherArmed = false
            hl.exec_cmd("qs -c MacShell ipc call switcher commit $(date +%s%3N)")
        end
    elseif code == 23 and state == 1 and altHeld > 0 then  -- Tab
        switcherArmed = true
    end
end)
hl.bind(mod .. " + W",          exec(SCRIPTS .. "/wallpaper.sh --random"))
hl.bind(mod .. " + SHIFT + W",  qs("wallpapers toggle"))
hl.bind(mod .. " + ALT + W",    exec(SCRIPTS .. "/livewall.sh --random"))
hl.bind(mod .. " + ALT + SHIFT + W", exec(SCRIPTS .. "/livewall.sh --pick"))
hl.bind(mod .. " + CTRL + W",   exec(SCRIPTS .. "/livewall.sh --toggle"))
hl.bind(mod .. " + V",          qs("spotlight clipboard"))
hl.bind(mod .. " + SHIFT + V",  exec("cliphist list | rofi -dmenu | cliphist delete"))

-- Screenshots (MacShell): region / whole screen / window, saved to ~/Pictures/Screenshot
hl.bind("Print",               qs("screenshot region"))
hl.bind("SHIFT + Print",       qs("screenshot screen"))
hl.bind(mod .. " + Print",     qs("screenshot window"))

-- Power menu
hl.bind(mod .. " + Delete", exec("pkill -x wlogout || GTK_THEME=Adwaita:dark wlogout -b 5 -c 0 -r 0 -L 360 -R 360 -T 400 -B 400 -l ~/.config/wlogout/layout -C ~/.config/wlogout/style.css"))

-- Windows-style snap: left/right half, up = maximize, down = restore (or minimize)
hl.bind(mod .. " + left",  exec(WINCTL .. " snap l"))
hl.bind(mod .. " + right", exec(WINCTL .. " snap r"))
hl.bind(mod .. " + up",    exec(WINCTL .. " up"))
hl.bind(mod .. " + down",  exec(WINCTL .. " down"))

-- Resize with SUPER+CTRL+arrows (hold to repeat)
hl.bind(mod .. " + CTRL + left",  hl.dsp.window.resize({ x = -40, y = 0,   relative = true }), { repeating = true })
hl.bind(mod .. " + CTRL + right", hl.dsp.window.resize({ x = 40,  y = 0,   relative = true }), { repeating = true })
hl.bind(mod .. " + CTRL + up",    hl.dsp.window.resize({ x = 0,   y = -40, relative = true }), { repeating = true })
hl.bind(mod .. " + CTRL + down",  hl.dsp.window.resize({ x = 0,   y = 40,  relative = true }), { repeating = true })

-- Mouse: drag to move, right-drag to resize
hl.bind(mod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Workspaces 1-10, and move the window there
for i = 1, 10 do
    local key = i % 10
    hl.bind(mod .. " + " .. key,             hl.dsp.focus({ workspace = tostring(i) }))
    hl.bind(mod .. " + SHIFT + " .. key,     hl.dsp.window.move({ workspace = tostring(i) }))
end

-- Display management
hl.bind(mod .. " + P",         exec(SCRIPTS .. "/display-toggle.sh extend"))
hl.bind(mod .. " + SHIFT + P", exec(SCRIPTS .. "/display-toggle.sh mirror"))
hl.bind(mod .. " + CTRL + P",  exec(SCRIPTS .. "/display-toggle.sh reset"))
hl.bind(mod .. " + ALT + P",   exec("nwg-displays"))

-- Volume / brightness keys
hl.bind("XF86AudioRaiseVolume",  exec("wpctl set-volume -l 1.0 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume",  exec("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),        { locked = true, repeating = true })
hl.bind("XF86AudioMute",         exec("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),       { locked = true })
hl.bind("XF86AudioMicMute",      exec("wpctl set-mute @DEFAULT_SOURCE@ toggle"),           { locked = true })
hl.bind("XF86MonBrightnessUp",   exec("brightnessctl set +10%"),                           { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", exec("brightnessctl set 10%-"),                           { locked = true, repeating = true })


----------------------
---- WINDOW RULES ----
----------------------

-- Windows-style stacking: everything floats so the clicked window comes to the front.
-- scripts/winctl.sh places windows (remembered size/position per app, cascaded defaults).
hl.window_rule({ name = "float-all", match = { class = ".*" }, float = true })
-- App maximize requests would make a real maximize that stays above other windows
hl.window_rule({ name = "no-app-maximize", match = { class = ".*" }, suppress_event = "maximize" })
hl.window_rule({ name = "kitty-no-max", match = { class = "^(kitty)$" }, suppress_event = "maximize fullscreen" })
hl.window_rule({ name = "kitty-size", match = { class = "^(kitty)$" }, float = true, size = "(monitor_w*0.5) (monitor_h*0.55)", center = true })
hl.window_rule({ name = "thunar", match = { class = "^(thunar)$" }, float = true, center = true })
-- Only main browser windows get the big size; dialogs (new folder, rename, progress) keep natural size
hl.window_rule({ name = "thunar-size", match = { class = "^(thunar)$", title = ".* - Thunar$" }, size = "(monitor_w*0.5) (monitor_h*0.55)" })
hl.window_rule({ name = "macshell-settings", match = { title = "^(macshell Settings)$" }, float = true, center = true })

-- No close animation for the slurp/hyprpicker overlays, or grim captures them mid-slide
hl.layer_rule({ name = "no-anim-pickers", match = { namespace = "^(selection|hyprpicker)$" }, no_anim = true })
-- winctl's drag-snap preview (MacShell) fades itself
hl.layer_rule({ name = "no-anim-snap-preview", match = { namespace = "^(snap-preview)$" }, no_anim = true })


require("look")
require("plugins")
